const listSalesReturns = `-- name: ListSalesReturns :many
SELECT r.id, r.number, r.sales_order_id, r.invoice_id, r.order_type, r.channel_id, r.sub_channel_id, r.party_type, r.party_id, r.party_name, r.source_location_id, r.return_date, r.settlement_method, r.requires_verification, r.note, r.send_back_note, r.verified_by, r.verified_at, r.verify_note, r.pickup_required, r.pickup_user_id, r.pickup_assigned_at, r.picked_up_at, r.pickup_note, r.pickup_file_ids, r.received_by, r.received_at, r.receive_note, r.documentation_file_ids, r.inbound_id, r.inbound_number, r.return_amount, r.cost_amount, r.status, r.cancel_reason, r.posted_at, r.journal_entry_id, r.created_at, r.created_by, r.updated_at, r.updated_by, r.version, r.deleted_at, r.deleted_by, coalesce(o.number, '')::text AS order_number, coalesce(i.number, '')::text AS invoice_number
FROM sales_returns r
JOIN sales_orders o ON o.id = r.sales_order_id
LEFT JOIN invoices i ON i.id = r.invoice_id
WHERE r.deleted_at IS NULL
  AND (cardinality($1::text[]) = 0 OR r.status = ANY($1::text[]))
  AND ($2::uuid IS NULL OR r.sales_order_id = $2::uuid)
  AND ($3::uuid IS NULL OR r.party_id = $3::uuid)
  AND ($4::uuid IS NULL OR r.pickup_user_id = $4::uuid)
  AND ($5::text IS NULL OR r.number ILIKE '%' || $5::text || '%'
       OR r.party_name ILIKE '%' || $5::text || '%'
       OR o.number ILIKE '%' || $5::text || '%')
ORDER BY r.created_at DESC
LIMIT $7 OFFSET $6
`

